import 'package:zonai/src/domain/gen/client_schema_document.dart';
import 'package:zonai/src/domain/gen/client_settings.dart';

/// The header every generated file carries, matching the precedent set by
/// `lib/src/internal/internal_db_migrations.dart`.
///
/// Half of the write guard: the manifest tells the *generator* what it owns,
/// this tells a *human* who opened the file by mistake.
const kGeneratedClientHeader = '// GENERATED CODE - DO NOT MODIFY BY HAND';

/// Everything an emitter is given. Deliberately just the schema and the
/// config — an emitter that needed a live database would be one that could not
/// run in `--check`.
final class ClientGenerationInput {
  const ClientGenerationInput({
    required this.schema,
    required this.settings,
    required this.generatorVersion,
  });

  final ClientSchemaDocument schema;
  final ClientSettings settings;
  final String generatorVersion;
}

/// Turns a schema into files. The seam the real Dart emitter plugs into.
///
/// Returns file *contents* keyed by path relative to the output directory —
/// not writes. Everything downstream (the manifest, the guard, `--check`)
/// needs to compare a generation against disk without performing it, and that
/// is only possible while the output is still a value.
abstract interface class ClientEmitter {
  Map<String, String> emit(ClientGenerationInput input);
}

/// Placeholder emitter: one header-carrying file naming the tables it would
/// have generated.
///
/// Real enough to exercise the manifest, the guard and `--check` end to end,
/// and honest enough that nobody mistakes its output for a working client.
final class StubClientEmitter implements ClientEmitter {
  const StubClientEmitter();

  static const outputFileName = 'zonai_client.g.dart';

  @override
  Map<String, String> emit(ClientGenerationInput input) {
    final buffer = StringBuffer()
      ..writeln(kGeneratedClientHeader)
      ..writeln('// Generated by zonai ${input.generatorVersion}.')
      ..writeln('// Schema hash: ${input.schema.hash}')
      ..writeln('//')
      ..writeln('// The typed client emitter is not implemented yet. This file')
      ..writeln(
        '// is a placeholder so the generation pipeline -- schema.json,',
      )
      ..writeln('// the manifest, the write guard and `--check` -- is real and')
      ..writeln('// testable ahead of it.')
      ..writeln('//')
      ..writeln('// A typed API says nothing about permission: `canView` /')
      ..writeln('// `canList` / `canUpdate` still reject at runtime.')
      ..writeln();

    for (final entry in input.schema.tables.entries) {
      final shape = entry.value;
      final row =
          input.settings.rowNameFor(entry.key) ?? _defaultRowName(entry.key);
      buffer.writeln(
        '// ${entry.key}: $row'
        '${shape.isView ? ' (view, read-only)' : ''}'
        ' -- ${shape.columns.length} column(s)',
      );
    }

    return {outputFileName: buffer.toString()};
  }

  /// §10.1: no singularization. `posts` → `PostsRow`, never `Post`.
  static String _defaultRowName(String table) {
    final pascal = table
        .split(RegExp(r'[_\s]+'))
        .where((part) => part.isNotEmpty)
        .map((part) => part[0].toUpperCase() + part.substring(1))
        .join();
    return '${pascal}Row';
  }
}
